from PIL import Image
import numpy as np

def decode_barn_pattern(image_path):
    # Open and convert image to numpy array
    img = Image.open(image_path)
    img_array = np.array(img)

    # Get center area where barn quilt pattern is likely to be
    height, width = img_array.shape[:2]
    center_y = height // 2
    center_x = width // 2
    size = min(height, width) // 2

    # Extract square region around center
    y_start = max(0, center_y - size)
    y_end = min(height, center_y + size)
    x_start = max(0, center_x - size)
    x_end = min(width, center_x + size)

    center_region = img_array[y_start:y_end, x_start:x_end]

    # Convert to binary pattern based on brightness
    grayscale = np.mean(center_region, axis=2)
    binary = grayscale > np.mean(grayscale)

    # Try different grid sizes (4x4, 8x8, 16x16)
    grid_sizes = [4, 8, 16]

    for grid_size in grid_sizes:
        print(f"\nAnalyzing {grid_size}x{grid_size} grid pattern:")
        # Resize binary array to grid size
        h_step = binary.shape[0] // grid_size
        w_step = binary.shape[1] // grid_size

        grid = np.zeros((grid_size, grid_size), dtype=bool)
        for i in range(grid_size):
            for j in range(grid_size):
                block = binary[i*h_step:(i+1)*h_step, j*w_step:(j+1)*w_step]
                grid[i,j] = np.mean(block) > 0.5

        # Print grid pattern
        for row in grid:
            print(''.join(['#' if x else '.' for x in row]))

        # Try to decode the pattern in different ways

        # As ASCII (rows)
        print("\nTrying ASCII decoding (rows):")
        for row in grid:
            binary_str = ''.join(['1' if x else '0' for x in row])
            if len(binary_str) >= 8:
                for i in range(0, len(binary_str)-7, 8):
                    try:
                        char = chr(int(binary_str[i:i+8], 2))
                        if char.isprintable():
                            print(f"Row {binary_str[i:i+8]} = '{char}'")
                    except:
                        pass

        # As ASCII (columns)
        print("\nTrying ASCII decoding (columns):")
        for col in grid.T:
            binary_str = ''.join(['1' if x else '0' for x in col])
            if len(binary_str) >= 8:
                for i in range(0, len(binary_str)-7, 8):
                    try:
                        char = chr(int(binary_str[i:i+8], 2))
                        if char.isprintable():
                            print(f"Column {binary_str[i:i+8]} = '{char}'")
                    except:
                        pass

        # Try morse code interpretation
        print("\nTrying Morse code interpretation:")
        for row in grid:
            morse = ''.join(['-' if x else '.' for x in row])
            print(morse)

        # Try to find any repeating patterns
        print("\nLooking for repeating patterns:")
        all_patterns = {}
        for i in range(grid_size-1):
            for j in range(grid_size-1):
                for size in range(2, min(grid_size-i, grid_size-j)):
                    pattern = grid[i:i+size, j:j+size]
                    pattern_str = '\n'.join([''.join(['1' if x else '0' for x in row]) for row in pattern])
                    if pattern_str in all_patterns:
                        all_patterns[pattern_str] += 1
                    else:
                        all_patterns[pattern_str] = 1

        # Print patterns that appear more than once
        for pattern, count in all_patterns.items():
            if count > 1:
                print(f"\nPattern appears {count} times:")
                print(pattern)

        # Try diagonal pattern
        print("\nDiagonal pattern:")
        diag = np.diag(grid)
        diag_str = ''.join(['1' if x else '0' for x in diag])
        print(f"Main diagonal: {diag_str}")
        if len(diag_str) >= 8:
            try:
                char = chr(int(diag_str[:8], 2))
                if char.isprintable():
                    print(f"Diagonal ASCII: '{char}'")
            except:
                pass

